const BASE_URL = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000";

export type SourceType =
  | "feedback"
  | "study"
  | "sales"
  | "option_list"
  | "web"
  | "external_stat"
  | "feedback_external";

export type Category =
  | "exterior"
  | "interior"
  | "comfort_space"
  | "infotainment_digital"
  | "driving_experience"
  | "range_charging"
  | "driver_assistance"
  | "quality_perception"
  | "variants_packages";

export type SignalKind =
  | "complaint"
  | "unmet_need"
  | "delight"
  | "competitor_advantage"
  | "trend";

export type EvidenceLevel = "A" | "B" | "C" | "D";
export type RequirementStatus = "proposed" | "challenged" | "approved" | "rejected";
export type Effort = "S" | "M" | "L";
export type ActorType = "ai" | "human" | "system";

export interface Actor {
  type: ActorType;
  name: string;
}

export interface Evidence {
  id: string;
  source_type: SourceType;
  source_name: string;
  derivative?: string;
  market?: string;
  text: string;
  url: string | null;
  retrieved_at: string | null;
  polarity: -1 | 0 | 1;
  meta: Record<string, string | number | boolean | null | undefined>;
}

export interface StudyLink {
  attribute: string;
  importance: number;
  dissatisfaction: number;
}

export interface Signal {
  id: string;
  kind: SignalKind;
  category: Category;
  title: string;
  summary: string;
  evidence_ids: string[];
  mention_count: number;
  source_types: SourceType[];
  conflicts_with: string[];
  segments?: Record<string, Record<string, number>>;
  study_link?: StudyLink | null;
}

export interface ScoreFactor {
  value: number;
  weight: number;
  contribution: number;
  explanation: string;
}

export type OfferCheckStatus = "not_offered" | "optional" | "standard" | "unknown";

export interface OfferCheck {
  status: OfferCheckStatus | string;
  note: string;
  option_code: string | null;
}

export interface Robustness {
  rank_min: number;
  rank_max: number;
  top3_share: number;
  runs: number;
}

export interface SegmentConflict {
  dimension: string;
  segment_a?: string;
  segment_b?: string;
  statement: string;
  a_count?: number;
  b_count?: number;
  evidence_ids?: string[];
  signal_ids?: string[];
}

export interface BusinessContext {
  volume_2025: number | null;
  volume_2030: number | null;
  growth_pct: number | null;
  market_share: number | null;
  note: string;
}

export interface Requirement {
  id: string;
  title: string;
  description: string;
  acceptance_criterion: string;
